-- EldoUI's texts in German (deDE): the texts that are not in EldoUI's Danish list (this fork's own, and EldoUI's own that the Danish pack lacks).
-- English is the key; a text missing here shows in English. The player is
-- addressed with "Ihr/Euch" and game terms are the ones the deDE client
-- uses, as in the Loot Guide's German table. Keep every %s, %d, {token} and
-- |c...|r code exactly as it is. Built with tools/locale/deDE.py.
-- This folder loads only when Deutsch is picked under General > EldoUI language
-- (or on a German client), and the table is built then. It is its own addon,
-- so EldoUI comes from its global.
local E = EldoUI
if not E then return end
-- Later tables for the same language add keys (E:RegisterLocale), so these
-- join the four files before it. `check` keeps every key here a string of
-- EldoUI's code that is not in the Danish list.
E:RegisterLocale("deDE", function() return {
	["%d action bars turned on or off"] = { one = "%d Aktionsleiste ein- oder ausgeschaltet", other = "%d Aktionsleisten ein- oder ausgeschaltet" },
	["%d bars change"] = { one = "%d Leiste ändert sich", other = "%d Leisten ändern sich" },
	["%d run Lua code"] = "%d davon führen Lua-Code aus",
	["%d. %s: %.2f ms/s (%d%%), %d calls, slowest %.2f ms (%s)"] = "%d. %s: %.2f ms/s (%d%%), %d Aufrufe, langsamster %.2f ms (%s)",
	["%s is no longer in your bags."] = "%s ist nicht mehr in Euren Taschen.",
	["%s is on your cursor: click outside your bags to destroy it (the game asks first), drop it on an open vendor window to sell it, or put it back in a bag."] = "%s hängt an Eurem Mauszeiger: Ein Klick außerhalb der Taschen zerstört den Gegenstand (das Spiel fragt vorher), auf einem offenen Händlerfenster abgelegt wird er verkauft. Oder legt ihn zurück in eine Tasche.",
	["%s runs out in %s."] = "%s läuft in %s aus.",
	["%s stays off the Quest Item Bar. \"Show hidden items again\" on its options page brings it back."] = "%s erscheint nicht mehr auf der Questgegenstandsleiste. „Ausgeblendete Gegenstände zeigen“ auf ihrer Optionsseite holt Ausgeblendetes zurück.",
	["%s wants to send you EldoUI settings. Answer your open question first; they can offer again in %d seconds."] = "%s möchte Euch EldoUI-Einstellungen senden. Beantwortet zuerst Eure offene Frage; ein neues Angebot ist in %d Sekunden möglich.",
	["%s, sells for %s"] = "%s, Verkaufspreis %s",
	["(runs Lua code)"] = "(führt Lua-Code aus)",
	["+%s XP"] = "+%s EP",
	["A \"World buffs\" column with each member's count in the Ready Check Report."] = "Eine Spalte „Weltbuffs“ mit der Anzahl jedes Mitglieds im Bereitschaftsbericht.",
	["A bar with every quest item in your bags that you can use, and the items that start a quest. A click or the button's key uses the item; the bar changes only out of combat."] = "Eine Leiste mit jedem benutzbaren Questgegenstand aus Euren Taschen und den Gegenständen, die eine Quest beginnen. Ein Klick oder die Taste des Platzes benutzt den Gegenstand; die Leiste ändert sich nur außerhalb des Kampfs.",
	["A block other addons can show: Titan Panel, ChocolateBar and the like list it as \"EldoUI: name\". It is kept up to date while it is chosen here, also in combat. A block taken out again stays in their list until a reload."] = "Ein Datentext, den andere Addons zeigen können: Titan Panel, ChocolateBar und ähnliche führen ihn als „EldoUI: Name“. Er bleibt aktuell, solange er hier gewählt ist, auch im Kampf. Wieder herausgenommen bleibt er bis zum nächsten Neuladen in ihrer Liste.",
	["A button glows for a few seconds when a new quest item lands on it (look under the Glows page)."] = "Ein Platz leuchtet einige Sekunden lang, wenn ein neuer Questgegenstand darauf landet (die Optik steht auf der Seite „Leuchteffekte“).",
	["A button in the minimap's addon button bin (on the map's edge while the bin is off) folds RestedXP's list of every step away and shows it again, the same as RestedXP's option \"Show step list\". The current step card and the arrow stay. EldoUI gives the list back at the height you had. A key for it: Key Bindings > AddOns > EldoUI. Needs the Minimap module."] = "Eine Schaltfläche im Addon-Knopfsammler der Minikarte (am Kartenrand, solange der Knopfsammler aus ist) klappt RestedXPs Liste aller Schritte ein und zeigt sie wieder, wie RestedXPs Option „Schrittliste anzeigen“. Die aktuelle Schrittkarte und der Pfeil bleiben. EldoUI gibt die Liste in der Höhe zurück, die sie vorher hatte. Eine Taste dafür: Tastaturbelegung > AddOns > EldoUI. Benötigt das Modul Minikarte.",
	["A button of the Quest Item Bar glows for a few seconds when a new quest item lands on it."] = "Ein Platz der Questgegenstandsleiste leuchtet einige Sekunden lang, wenn ein neuer Questgegenstand darauf landet.",
	["A card when your ordinary bags get down to a few free slots, with the five cheapest things you carry. A click on one puts it on your cursor: click outside your bags to destroy it (the game asks first), or drop it on an open vendor window to sell it. Never in combat."] = "Eine Karte, wenn in Euren normalen Taschen nur noch wenige Plätze frei sind, mit den fünf billigsten Gegenständen, die Ihr dabeihabt. Ein Klick auf einen legt ihn an den Mauszeiger: Ein Klick außerhalb der Taschen zerstört ihn (das Spiel fragt vorher), auf einem offenen Händlerfenster abgelegt wird er verkauft. Nie im Kampf.",
	["A guild member's DKP or EPGP standing, read from the guild notes (Raid Loot > Guild points)."] = "Der DKP- oder EPGP-Stand eines Gildenmitglieds, gelesen aus den Gildennotizen (Schlachtzugsbeute > Gildenpunkte).",
	["A restore starts with only the action bars and which bars are on checked."] = "Eine Wiederherstellung beginnt mit nur den Aktionsleisten und der Auswahl, welche Leisten an sind, angehakt.",
	["A snapshot holds your action slots, which action bars are on, macros, key bindings and Edit Mode layout. Restore shows each change first and can be undone."] = "Ein Schnappschuss enthält Eure Aktionsplätze, welche Aktionsleisten an sind, Makros, Tastenbelegungen und das Layout des Bearbeitungsmodus. Wiederherstellen zeigt jede Änderung vorher und lässt sich rückgängig machen.",
	["A soft shadow under every line, on top of the outline."] = "Ein weicher Schatten unter jeder Zeile, zusätzlich zur Kontur.",
	["A soft shadow under every number, on top of the outline."] = "Ein weicher Schatten unter jeder Zahl, zusätzlich zur Kontur.",
	["A thin bar at the bottom of each frame while the member casts: casts fill, channels empty, gray when the cast can't be interrupted."] = "Eine schmale Leiste am unteren Rand jedes Rahmens, solange das Mitglied zaubert: Zauber füllen sie, kanalisierte Zauber leeren sie, grau, wenn sich der Zauber nicht unterbrechen lässt.",
	["Action Bar %d: off"] = "Aktionsleiste %d: aus",
	["Action Bar %d: on"] = "Aktionsleiste %d: an",
	["Action bars not turned on or off (%s)"] = "Aktionsleisten nicht ein- oder ausgeschaltet (%s)",
	["Active item scale"] = "Skalierung der aktiven Gegenstände",
	["Active target scale"] = "Skalierung der aktiven Ziele",
	["Acts for you when turned on: a set you click in combat (set buttons or the Gear block) goes on once combat ends, or once you are alive again. Only your last click counts; click that set again, or the set you wear, to keep your gear. Off by default."] = "Handelt für Euch, wenn eingeschaltet: Ein Set, das Ihr im Kampf anklickt (Set-Schaltflächen oder der Block „Ausrüstung“), wird angelegt, sobald der Kampf endet oder Ihr wieder lebt. Nur Euer letzter Klick zählt; klickt dasselbe Set noch einmal oder das Set, das Ihr tragt, um Eure Ausrüstung zu behalten. Standardmäßig aus.",
	["After combat"] = "Nach dem Kampf",
	["After combat: %s"] = "Nach dem Kampf: %s",
	["After the names"] = "Hinter den Namen",
	["Also the item the quest log names for a quest that is ready to turn in."] = "Auch den Gegenstand, den das Questlog für eine Quest nennt, die zum Abgeben bereit ist.",
	["Arrow scale"] = "Pfeilskalierung",
	["Arrow text size"] = "Schriftgröße am Pfeil",
	["At login, when your bars are empty, your key bindings differ, your Edit Mode layout is gone or two or more action bars are turned off, offers to review a restore. Nothing is restored without your click."] = "Wenn beim Einloggen Eure Leisten leer sind, Eure Tastenbelegungen abweichen, Euer Layout des Bearbeitungsmodus fehlt oder zwei oder mehr Aktionsleisten ausgeschaltet sind, wird angeboten, eine Wiederherstellung zu prüfen. Ohne Euren Klick wird nichts wiederhergestellt.",
	["Bag space"] = "Taschenplatz",
	["Bags almost full"] = "Taschen fast voll",
	["Battleground map"] = "Schlachtfeldkarte",
	["Block %d for other addons"] = "Datentext %d für andere Addons",
	["Careful: %d of these macros run Lua code (%s). Add them only if you trust where the string came from."] = "Vorsicht: %d dieser Makros führen Lua-Code aus (%s). Fügt sie nur hinzu, wenn Ihr der Herkunft des Strings vertraut.",
	["Cast bar height"] = "Höhe der Zauberleiste",
	["Checked in the restore window: turn action bars 2 to 8 on or off as in the snapshot (Options > Action Bars). They show after a reload."] = "Im Wiederherstellungsfenster angehakt: schaltet die Aktionsleisten 2 bis 8 ein oder aus wie im Schnappschuss (Optionen > Aktionsleisten). Sie erscheinen nach einem Neuladen.",
	["Clear your cursor first."] = "Leert zuerst Euren Mauszeiger.",
	["Click: fold the list of every step away. The current step card and the arrow stay."] = "Klick: die Liste aller Schritte einklappen. Die aktuelle Schrittkarte und der Pfeil bleiben.",
	["Click: show the list of every step of the guide."] = "Klick: die Liste aller Schritte des Guides zeigen.",
	["Clock and stopwatch"] = "Uhr und Stoppuhr",
	["Column in the Ready Check Report"] = "Spalte im Bereitschaftsbericht",
	["Critical hits and other sticky lines start white and turn to their color."] = "Kritische Treffer und andere haftende Zeilen erscheinen weiß und nehmen dann ihre Farbe an.",
	["Critical hits start white and turn to their color."] = "Kritische Treffer erscheinen weiß und nehmen dann ihre Farbe an.",
	["DKP or EPGP standings from the guild notes, after the names on the SR and TMB lines, on guild members' tooltips and in the Info Bar block \"Guild points\". Automatic: EPGP notes (\"1250,830\") and DKP notes with a label (\"Net:350\", \"DKP: 350\"). DKP also takes a plain number."] = "DKP- oder EPGP-Stände aus den Gildennotizen, hinter den Namen in den SR- und TMB-Zeilen, im Tooltip von Gildenmitgliedern und im Infoleisten-Block „Gildenpunkte“. Automatisch: EPGP-Notizen („1250,830“) und DKP-Notizen mit Kennung („Net:350“, „DKP: 350“). DKP nimmt auch eine bloße Zahl.",
	["Each player's standing after their name on the SR and TMB lines. The chat post of the reservations never carries it."] = "Der Stand jedes Spielers hinter seinem Namen in den SR- und TMB-Zeilen. Der Chat-Beitrag mit den Reservierungen enthält ihn nie.",
	["Eating and drinking"] = "Essen und Trinken",
	["EldoUI Quest Item Bar"] = "EldoUI Questgegenstandsleiste",
	["EldoUI timing"] = "EldoUI-Zeitmessung",
	["EldoUI timing, %s measured (%s):"] = "EldoUI-Zeitmessung, %s gemessen (%s):",
	["EldoUI: %s goes on once you are alive again. Click it again to keep your gear."] = "EldoUI: %s wird angelegt, sobald Ihr wieder lebt. Ein zweiter Klick darauf behält Eure Ausrüstung.",
	["EldoUI: %s goes on when combat ends. Click it again to keep your gear."] = "EldoUI: %s wird angelegt, sobald der Kampf endet. Ein zweiter Klick darauf behält Eure Ausrüstung.",
	["EldoUI: no set change after combat."] = "EldoUI: kein Setwechsel nach dem Kampf.",
	["Empty for now: the next quest item you can use comes here."] = "Noch leer: Der nächste benutzbare Questgegenstand kommt hierher.",
	["Equip after combat"] = "Nach dem Kampf anlegen",
	["Every quest item in your bags that you can use gets a button: click it or press its key to use the item. Items that start a quest come too. The bar changes only out of combat. The Quest Tracker's quest item button keeps the tracked quest's item on its own key."] = "Jeder benutzbare Questgegenstand in Euren Taschen bekommt einen Platz: Klickt darauf oder drückt seine Taste, um den Gegenstand zu benutzen. Gegenstände, die eine Quest beginnen, kommen dazu. Die Leiste ändert sich nur außerhalb des Kampfs. Die Schaltfläche für Questgegenstand der Questverfolgung behält den Gegenstand der verfolgten Quest auf ihrer eigenen Taste.",
	["Fit RestedXP to this game language"] = "RestedXP an die Spielsprache anpassen",
	["Flash big lines"] = "Große Zeilen aufblitzen lassen",
	["Flash critical hits"] = "Kritische Treffer aufblitzen lassen",
	["Font of plate numbers. Default: the UI font."] = "Schriftart der Plakettenzahlen. Standard: die UI-Schriftart.",
	["Free slots left: %d."] = "Noch freie Plätze: %d.",
	["From the note"] = "Aus der Notiz",
	["Game language"] = "Spielsprache",
	["Goes on when combat ends."] = "Wird angelegt, sobald der Kampf endet.",
	["Gray count"] = "Anzahl in Grau",
	["Guide font size"] = "Schriftgröße des Guides",
	["Guild points"] = "Gildenpunkte",
	["Guild points (DKP and EPGP)"] = "Gildenpunkte (DKP und EPGP)",
	["Height of the cast bar. From 8 pixels it has room for the spell name."] = "Höhe der Zauberleiste. Ab 8 Pixeln hat sie Platz für den Zaubernamen.",
	["Hint when the bags are almost full"] = "Hinweis bei fast vollen Taschen",
	["Hover a button of the Quest Item Bar and press a key, then click Save."] = "Zeigt auf einen Platz der Questgegenstandsleiste, drückt eine Taste und klickt dann auf „Speichern“.",
	["How many minutes before the end the warning comes."] = "Wie viele Minuten vor dem Ende die Warnung kommt.",
	["How many world buffs the member has (World Buffs module)."] = "Wie viele Weltbuffs das Mitglied hat (Modul Weltbuffs).",
	["In a party or raid, where hit numbers on plates are off, Blizzard's damage numbers show instead: only your own hits."] = "In einer Gruppe oder einem Schlachtzug, wo die Trefferzahlen auf Namensplaketten aus sind, zeigt das Spiel stattdessen Blizzards Schadenszahlen: nur Eure eigenen Treffer.",
	["Items that start a quest"] = "Gegenstände, die Quests beginnen",
	["Items with a \"!\" that start a quest you don't have yet. A click shows the quest."] = "Gegenstände mit „!“, die eine Quest beginnen, die Ihr noch nicht habt. Ein Klick zeigt die Quest.",
	["Items you left off the bar with Shift-right-click come back."] = "Gegenstände, die Ihr mit Umschalt-Rechtsklick von der Leiste genommen habt, kommen zurück.",
	["Ivory, golden critical hits"] = "Elfenbein, kritische Treffer golden",
	["Make room"] = "Platz schaffen",
	["Make room: the cheapest things you carry."] = "Platz schaffen: die billigsten Gegenstände, die Ihr dabeihabt.",
	["Names can't contain | or line breaks."] = "Namen dürfen kein | und keine Zeilenumbrüche enthalten.",
	["No DKP or EPGP standings in the guild notes."] = "Keine DKP- oder EPGP-Stände in den Gildennotizen.",
	["No RestedXP guide is loaded."] = "Kein RestedXP-Guide geladen.",
	["No key bound (Quest Item Bar > Bind keys)"] = "Keine Taste belegt (Questgegenstandsleiste > Tasten belegen)",
	["Nothing measured yet."] = "Noch nichts gemessen.",
	["Nothing to offer: the rest is needed or kept, has no vendor price, or is food, a reagent, ammo or the like."] = "Nichts anzubieten: Der Rest wird gebraucht oder behalten, hat keinen Händlerpreis oder ist Essen, ein Reagenz, Munition oder Ähnliches.",
	["Officer note"] = "Offiziersnotiz",
	["One chat line, only for you, when one of your world buffs has this many minutes left."] = "Eine Chatzeile, nur für Euch, wenn einer Eurer Weltbuffs nur noch so viele Minuten hat.",
	["Only the splash"] = "Nur das Platschen",
	["Opens keybind mode with every button of the bar shown: hover one, press a key, then click Save. The first button holds the first quest item in your bags, and so on."] = "Öffnet den Tastenbelegungsmodus mit allen Plätzen der Leiste: Zeigt auf einen, drückt eine Taste und klickt dann auf „Speichern“. Der erste Platz hält den ersten Questgegenstand in Euren Taschen, und so weiter.",
	["Plays the signal now."] = "Spielt das Signal jetzt ab.",
	["Profile %s switched off: %s. Blizzard's own versions come fully back after a reload."] = "Profil %s hat ausgeschaltet: %s. Blizzards eigene Versionen kehren nach einem Neuladen vollständig zurück.",
	["Public note"] = "Öffentliche Notiz",
	["Punch"] = "Wumms",
	["Punchy"] = "Kräftig",
	["Put it on the layout spot"] = "Auf den Layout-Platz setzen",
	["Puts RestedXP's text sizes and scales back as they were before EldoUI's change. A value you changed in RestedXP since stays yours."] = "Setzt RestedXPs Schriftgrößen und Skalierungen zurück, wie sie vor EldoUIs Änderung waren. Ein Wert, den Ihr seitdem in RestedXP geändert habt, bleibt Eurer.",
	["Puts it on your cursor: click outside your bags to destroy it (the game asks first), or drop it on an open vendor window to sell it."] = "Legt ihn an den Mauszeiger: Ein Klick außerhalb der Taschen zerstört ihn (das Spiel fragt vorher), auf einem offenen Händlerfenster abgelegt wird er verkauft.",
	["Quest Item Bar"] = "Questgegenstandsleiste",
	["Quest item %d (Quest Item Bar)"] = "Questgegenstand %d (Questgegenstandsleiste)",
	["Read standings"] = "Stände lesen",
	["RestedXP active items"] = "RestedXP: aktive Gegenstände",
	["RestedXP arrow and windows"] = "RestedXP-Pfeil und -Fenster",
	["RestedXP is not loaded."] = "RestedXP ist nicht geladen.",
	["RestedXP shows its guide text in the new size after a reload."] = "RestedXP zeigt den Guide-Text nach einem Neuladen in der neuen Größe.",
	["RestedXP step list"] = "RestedXP-Schrittliste",
	["RestedXP targets"] = "RestedXP: Ziele",
	["RestedXP's default"] = "RestedXPs Standard",
	["RestedXP's group names are fixed, and its free guides lead on into the paid ones."] = "Die Gruppennamen von RestedXP sind berichtigt, und die kostenlosen Guides führen in die gekauften weiter.",
	["RestedXP's paid guides are in English. On a client in another language EldoUI looks up the NPC names of the target macro in QuestieDB and keeps quest experience out of the monster count of the leveling report. On a German client it also fixes RestedXP's group names and leads the free guides on into the paid ones. RestedXP's own files stay as they are."] = "Die gekauften Guides von RestedXP sind auf Englisch. Bei einem Client in einer anderen Sprache sucht EldoUI die NPC-Namen des Zielmakros in QuestieDB nach und zählt in der Levelstatistik Erfahrung aus Quests nicht mehr als Erfahrung von Gegnern. Bei einem deutschen Client berichtigt es außerdem die Gruppennamen von RestedXP und führt die kostenlosen Guides in die gekauften weiter. Die Dateien von RestedXP bleiben, wie sie sind.",
	["RestedXP: sizes to fit EldoUI"] = "RestedXP: Größen passend zu EldoUI",
	["Save your action bars, which bars are on, macros, key bindings and Edit Mode layout, preview what a restore changes, and put them back with one click."] = "Speichert Eure Aktionsleisten, welche Leisten an sind, Makros, Tastenbelegungen und das Layout des Bearbeitungsmodus, zeigt vorab, was eine Wiederherstellung ändert, und stellt sie mit einem Klick zurück.",
	["Self-Found is on for this character: mail from other players can't be used."] = "„Selbstgefunden“ ist für diesen Charakter aktiv: Post von anderen Spielern kann nicht genutzt werden.",
	["Self-Found is on for this character: the auction house can't be used."] = "„Selbstgefunden“ ist für diesen Charakter aktiv: Das Auktionshaus kann nicht genutzt werden.",
	["Self-Found is on for this character: trading with other players is blocked."] = "„Selbstgefunden“ ist für diesen Charakter aktiv: Der Handel mit anderen Spielern ist gesperrt.",
	["Sets RestedXP's guide text and arrow text to the size of EldoUI's own text (General > Accessibility > Large text counts), and lets the arrow, the active items and the targets grow by as much. A window scale other than 100 % goes back to 100 %, since the larger text does the job. EldoUI asks first and shows which RestedXP profile changes. The guide text changes after a reload. Undo puts the old values back."] = "Stellt RestedXPs Guide-Text und den Text am Pfeil auf die Größe von EldoUIs eigenem Text (Allgemein > Barrierefreiheit > Große Schrift zählt mit) und lässt Pfeil, aktive Gegenstände und Ziele im selben Maß wachsen. Eine andere Fensterskalierung als 100 % geht auf 100 % zurück, denn der größere Text erledigt das schon. EldoUI fragt vorher und zeigt, welches RestedXP-Profil sich ändert. Der Guide-Text ändert sich nach einem Neuladen. Rückgängig stellt die früheren Werte wieder her.",
	["Show hidden items again"] = "Ausgeblendete Gegenstände zeigen",
	["Show now"] = "Jetzt zeigen",
	["Show or hide RestedXP's step list"] = "RestedXPs Schrittliste ein-/ausblenden",
	["Shows the card with the cheapest things you carry now (also /eui room)."] = "Zeigt jetzt die Karte mit den billigsten Gegenständen, die Ihr dabeihabt (auch /eui room).",
	["Signal when the meal is done"] = "Signal, wenn die Mahlzeit fertig ist",
	["Sizes to fit EldoUI"] = "Größen passend zu EldoUI",
	["Spell name on the cast bar"] = "Zaubername auf der Zauberleiste",
	["Starts a quest: a click shows it."] = "Beginnt eine Quest: Ein Klick zeigt sie.",
	["Step list button on the minimap"] = "Schrittlisten-Schaltfläche an der Minikarte",
	["Tall bold numbers with a thick outline and a shadow. Critical hits flash white, turn gold and punch out; hits are thrown off the enemy's nameplate."] = "Hohe, kräftige Zahlen mit dicker Kontur und Schatten. Kritische Treffer blitzen weiß auf, werden golden und springen mit Wumms heraus; Treffer fliegen von der Namensplakette des Gegners.",
	["Target names: %d translated with QuestieDB so far."] = "Zielnamen: bisher %d mit QuestieDB übersetzt.",
	["Target names: QuestieDB is not loaded, so RestedXP's own list stays."] = "Zielnamen: QuestieDB ist nicht geladen, daher bleibt es bei der eigenen Liste von RestedXP.",
	["Target names: reading QuestieDB's NPC names (%d%%)."] = "Zielnamen: Die NPC-Namen aus QuestieDB werden gelesen (%d%%).",
	["That name is too long."] = "Dieser Name ist zu lang.",
	["The RestedXP integration is off (Integrations > RestedXP)."] = "Die RestedXP-Einbindung ist aus (Integrationen > RestedXP).",
	["The XP each quest gives when you hand it in, after its title in the quest log, in the color of the finished quests on the XP bar (yellow unless you changed it). Hidden at the level cap."] = "Die EP, die jede Quest beim Abgeben gibt, hinter ihrem Titel im Questlog, in der Farbe der fertigen Quests auf der EP-Leiste (gelb, sofern Ihr sie nicht geändert habt). Auf der Höchststufe ausgeblendet.",
	["The action bars you turned on or off show after a reload."] = "Die ein- oder ausgeschalteten Aktionsleisten erscheinen nach einem Neuladen.",
	["The bar changes when combat ends."] = "Die Leiste ändert sich, sobald der Kampf endet.",
	["The card comes when this many slots or fewer are free."] = "Die Karte kommt, wenn so viele Plätze oder weniger frei sind.",
	["The game's button in the taskbar flashes while the game is in the background."] = "Die Schaltfläche des Spiels in der Taskleiste blinkt, solange das Spiel im Hintergrund läuft.",
	["The icon turns red while the game says your target is out of the item's range. Only for the items the quest log names."] = "Das Symbol wird rot, solange das Spiel meldet, dass Euer Ziel außer Reichweite des Gegenstands ist. Nur für die Gegenstände, die das Questlog nennt.",
	["The language of the Wowhead page. Game language follows your game client, so the page names items, quests and creatures the way the game does."] = "Die Sprache der Wowhead-Seite. „Spielsprache“ folgt Eurem Spielclient, so heißen Gegenstände, Quests und Kreaturen auf der Seite wie im Spiel.",
	["The name of the spell on the bar, when the bar is at least 8 pixels high."] = "Der Name des Zaubers auf der Leiste, wenn sie mindestens 8 Pixel hoch ist.",
	["The sound when your meal is done. None for silence."] = "Der Sound, wenn Eure Mahlzeit fertig ist. Keiner für Stille.",
	["The sound with the card. None for silence."] = "Der Sound zur Karte. Keiner für Stille.",
	["The step list changes after combat."] = "Die Schrittliste ändert sich nach dem Kampf.",
	["There is no profile with that name."] = "Es gibt kein Profil mit diesem Namen.",
	["This RestedXP guide shows no step list."] = "Dieser RestedXP-Guide zeigt keine Schrittliste.",
	["This RestedXP version has no step list switch."] = "Diese RestedXP-Version hat keinen Schalter für die Schrittliste.",
	["This list can't be imported from a string (%s)."] = "Diese Liste lässt sich nicht aus einem String importieren (%s).",
	["Throw"] = "Wurf",
	["Timing each module now. /eui perf shows the results, /eui perf stop ends it."] = "Jedes Modul wird jetzt gemessen. /eui perf zeigt die Ergebnisse, /eui perf stop beendet die Messung.",
	["Timing is not running. /eui perf starts it."] = "Die Zeitmessung läuft nicht. /eui perf startet sie.",
	["Timing started again from zero."] = "Zeitmessung von vorn gestartet.",
	["Titan Panel, ChocolateBar and other LibDataBroker displays can show Info Bar blocks once one of them is loaded."] = "Titan Panel, ChocolateBar und andere LibDataBroker-Anzeigen können Datentexte der Infoleiste zeigen, sobald eines davon geladen ist.",
	["Total: %.2f ms/s over %d calls."] = "Gesamt: %.2f ms/s bei %d Aufrufen.",
	["Toy box"] = "Spielzeugkiste",
	["Turn action bars 2 to 8 on or off as in the snapshot (Options > Action Bars). They show after a reload."] = "Die Aktionsleisten 2 bis 8 ein- oder ausschalten wie im Schnappschuss (Optionen > Aktionsleisten). Sie erscheinen nach einem Neuladen.",
	["Turn on the Quest Item Bar first."] = "Schaltet zuerst die Questgegenstandsleiste ein.",
	["Turns every other sound off while fishing: music, ambience, dialog, spoken errors, emote, pet and ping sounds. The sound effects stay on, since the splash is one of them; the game switches effects only all together, so spells, creatures and footsteps stay too. Sound in the background goes on, so you hear the splash with the game window behind another. Your own settings come back when fishing mode ends."] = "Schaltet beim Angeln jeden anderen Ton aus: Musik, Umgebungsgeräusche, Dialoge, gesprochene Fehlermeldungen, Emote-, Haustier- und Ping-Geräusche. Die Soundeffekte bleiben an, denn das Platschen ist einer davon; das Spiel schaltet Effekte nur alle zusammen, also bleiben auch Zauber, Kreaturen und Schritte hörbar. Ton im Hintergrund wird eingeschaltet, damit Ihr das Platschen auch hört, wenn das Spielfenster hinter einem anderen liegt. Eure eigenen Einstellungen kommen zurück, wenn der Angelmodus endet.",
	["Type a name first."] = "Gebt zuerst einen Namen ein.",
	["Undo the size change"] = "Größenänderung rückgängig machen",
	["Uses the game's equipment sets from the character window. Every swap happens out of combat."] = "Verwendet die Ausrüstungssets des Spiels aus dem Charakterfenster. Jeder Wechsel geschieht außerhalb des Kampfes.",
	["Warn before one runs out"] = "Warnen, bevor einer ausläuft",
	["When the Masque addon is loaded, let it skin these buttons (Masque lists them under EldoUI). EldoUI's own button art steps aside."] = "Ist das Addon Masque geladen, darf es diese Tasten skinnen (Masque führt sie unter EldoUI). EldoUIs eigene Tastengrafik tritt dann zurück.",
	["Which bars are on"] = "Welche Leisten an sind",
	["Which guild note holds the standings. The officer note counts only when the game lets you see it."] = "Welche Gildennotiz die Stände enthält. Die Offiziersnotiz zählt nur, wenn das Spiel sie Euch zeigt.",
	["Which items"] = "Welche Gegenstände",
	["While you eat or drink: a sound and a flash of the game in the taskbar once your health and mana are full, so you know when to get up. Food that gives Well Fed waits for the buff. Once per meal, out of combat only."] = "Beim Essen oder Trinken: ein Sound und ein Blinken des Spiels in der Taskleiste, sobald Gesundheit und Mana voll sind, damit Ihr wisst, wann Ihr aufstehen könnt. Bei Essen, das „Satt“ gibt, wartet es auf den Stärkungszauber. Einmal pro Mahlzeit, nur außerhalb des Kampfs.",
	["While your bobber is out the fishing key is Interact with target, so a press on a splash loots it. For that, fishing mode turns on the game's soft interact for mouse and keyboard and lets it reach the bobber (30 yards, in front of you); your own settings come back when fishing mode ends."] = "Solange Euer Schwimmer draußen ist, ist die Angeltaste Mit Ziel interagieren, sodass ein Druck bei einem Platschen ihn plündert. Dafür schaltet der Angelmodus die Soft-Interaktion des Spiels für Maus und Tastatur ein und gibt ihr die Reichweite bis zum Schwimmer (30 Meter, vor Euch); Eure eigenen Einstellungen kommen zurück, wenn der Angelmodus endet.",
	["World Buffs"] = "Weltbuffs",
	["World buffs"] = "Weltbuffs",
	["Wowhead language"] = "Wowhead-Sprache",
	["Writes the count of joined lines in gray, so the number stands out."] = "Schreibt die Anzahl zusammengefasster Zeilen in Grau, damit die Zahl heraussticht.",
	["XP in the quest log"] = "EP im Questlog",
	["You have no world buffs."] = "Ihr habt keine Weltbuffs.",
	["You placed %s yourself, so the layout leaves it where you put it. This puts it on the layout's spot instead, and later layouts move it too. Turning it off again gives your spot back until you log out."] = "Ihr habt %s selbst platziert, deshalb lässt das Layout es dort, wo Ihr es hingesetzt habt. Dies setzt es stattdessen auf den Platz des Layouts, und spätere Layouts verschieben es ebenfalls. Schaltet Ihr es wieder aus, bekommt Ihr Euren Platz zurück, bis Ihr Euch ausloggt.",
	["Your world buffs show in the Info Bar block \"World buffs\" (pick it for a slot on the Info Bar page), with the time each one has left."] = "Eure Weltbuffs erscheinen im Infoleisten-Block „Weltbuffs“ (auf der Seite Infoleiste einem Platz zuweisen), mit der Restzeit jedes einzelnen.",
	["Your world buffs with the time they have left, a warning before one runs out, and who in your group has which."] = "Eure Weltbuffs mit ihrer Restzeit, eine Warnung, bevor einer ausläuft, und wer in Eurer Gruppe welche hat.",
	["[stop | reset | copy]  time each module's events and timers; once started, /eui perf shows what it measured"] = "[stop | reset | copy]  Events und Timer jedes Moduls messen; läuft die Messung, zeigt /eui perf das Ergebnis",
	["action bars %s are turned off"] = "die Aktionsleisten %s sind ausgeschaltet",
	["already the same"] = "schon gleich",
	["equip (in combat: when it ends)"] = "anlegen (im Kampf: sobald er endet)",
	["equip a set (in combat: when it ends)"] = "ein Set anlegen (im Kampf: sobald er endet)",
	["kept where RestedXP puts it, like its guide window"] = "bleibt, wo RestedXP es hinsetzt, wie sein Guide-Fenster",
	["leave this item off the bar"] = "diesen Gegenstand von der Leiste nehmen",
	["placed once the setup is done, like the guide window"] = "wird platziert, sobald die Einrichtung fertig ist, wie das Guide-Fenster",
	["running"] = "läuft",
	["stopped"] = "beendet",
	["the cheapest things in your bags, to make room"] = "die billigsten Gegenstände in Euren Taschen, um Platz zu schaffen",
	["the game doesn't say which action bars are on"] = "das Spiel meldet nicht, welche Aktionsleisten an sind",
	["the game refused to turn the action bars on or off"] = "das Spiel hat das Ein- oder Ausschalten der Aktionsleisten abgelehnt",
	["this game client can't turn action bars on or off"] = "dieser Spielclient kann Aktionsleisten nicht ein- oder ausschalten",
	["v%s loaded. Type %s for options."] = "v%s geladen. Gebt %s ein, um die Optionen zu öffnen.",
} end)
